        show("if let Some(x) = n", &x);
    }
    // a shared reference to the value: the name gets a shared reference
    if let Some(x) = &n {
        show("if let Some(x) = &n", &x);
    }
    // a mutable reference: the name gets a mutable reference
    if let Some(x) = &mut n {
        *x += 1;
        show("if let Some(x) = &mut n", &x);
    }
    println!("n is now {n:?}");

    // the same for tuples
    let (a, _) = &pair;
    show("let (a, _) = &pair", &a);
    // a & in the pattern strips the reference by hand
    let &(b, _) = &pair;
    show("let &(b, _) = &pair", &b);
}

check-rows.rs.code:
// Backs the Rust cells in the tables on the page and a few one-line claims. Never shown.
use std::collections::HashMap;
use std::convert::Infallible;

struct Point {
    x: i32,
    y: i32,
}

enum Shape {
    Circle(f64),
    Square,
}

fn main() {
    // let Point { x, y } = p;  and  let Point { x: px, .. } = p;
    let p = Point { x: 3, y: -2 };
    let Point { x, y } = p;
    assert_eq!((x, y), (3, -2));
    let Point { x: px, .. } = p;
    assert_eq!(px, 3);

    // let Point { x, y } = &p;  gives references
    let Point { x, y } = &p;
    let (rx, ry): (&i32, &i32) = (x, y);
    assert_eq!((*rx, *ry), (3, -2));

    // let Point { x, y } = &mut p;  gives mutable references: write *x
    let mut q = Point { x: 3, y: -2 };
    let Point { x, y } = &mut q;
    *x += 10;
    *y += 1;
    assert_eq!((q.x, q.y), (13, -1));

    // a function parameter is a pattern
    fn manhattan(Point { x, y }: &Point) -> i32 {
        x.abs() + y.abs()
    }
    assert_eq!(manhattan(&p), 5);

    // (a, b) = (b, a);
    let (mut a, mut b) = (1, 2);
    (a, b) = (b, a);
    assert_eq!((a, b), (2, 1));

    // for (i, v) in xs.iter().enumerate()
    let xs = [10, 20];
    let pairs: Vec<(usize, &i32)> = xs.iter().enumerate().collect();
    assert_eq!(pairs, [(0, &10), (1, &20)]);

    // for (i, c) in s.char_indices()
    let indices: Vec<(usize, char)> = "aé!".char_indices().collect();
    assert_eq!(indices, [(0, 'a'), (1, 'é'), (3, '!')]);

    // let Some((key, value)) = s.split_once('=') else { .. };
    assert_eq!("mode=fast".split_once('='), Some(("mode", "fast")));
    assert_eq!("mode".split_once('='), None);
    let Some((key, value)) = "mode=fast".split_once('=') else {
        panic!("has an '='")
    };
    assert_eq!((key, value), ("mode", "fast"));

    // if let Some(v) = m.get(&k)  and  for (k, v) in &m
    let ages = HashMap::from([("ana", 30)]);
    assert!(matches!(ages.get("ana"), Some(30)));
    assert!(ages.get("zed").is_none());
    for (k, v) in &ages {
        assert_eq!((*k, *v), ("ana", 30));
    }

    // if let Shape::Circle(r) = o  and  let Shape::Circle(r) = o else { return };
    fn radius(o: &Shape) -> Option<f64> {
        let Shape::Circle(r) = o else {
            return None;
        };
        Some(*r)
    }
    assert_eq!(radius(&Shape::Circle(2.0)), Some(2.0));
    assert_eq!(radius(&Shape::Square), None);

    // if let [first, rest @ ..] = xs.as_slice()
    let list = vec![1, 2, 3];
    let [first, rest @ ..] = list.as_slice() else {
        panic!("not empty")
    };
    assert_eq!((*first, rest), (1, &[2, 3][..]));

    // let &x = r;  is the pattern form of  x = *r;  and  ref x  borrows
    let five = 5;
    let &v = &five;
    assert_eq!(v, 5);
    let name = Some(String::from("ana"));
    if let Some(ref s) = name {
        assert_eq!(s, "ana");
    }

    // an error type with no values cannot fail: Ok(x) always fits
    let sure: Result<u32, Infallible> = Ok(7);
    let Ok(n) = sure;
    assert_eq!(n, 7);

    println!("all rows hold");
}

destructure.rs.code:
struct Point {
    x: i32,
    y: i32,
}

struct Rgb(u8, u8, u8);

enum Shape {
    Circle { center: Point, radius: u32 },
    Rect(Point, Point),
}

fn describe(shape: &Shape) -> String {
    match shape {
        Shape::Circle {
            center: Point { x: 0, y: 0 },
            radius,
        } => format!("circle at the origin, radius {radius}"),
        Shape::Circle { center, radius } => {
            format!("circle at ({}, {}), radius {radius}", center.x, center.y)
        }
        Shape::Rect(Point { x: x1, y: y1 }, Point { x: x2, y: y2 }) => {
            format!("rect {} wide, {} high", x2 - x1, y2 - y1)
        }
    }
}

fn main() {
    // by field name, in any order; a new name after the colon
    let Point { y, x: px } = Point { x: 3, y: -2 };
    println!("px = {px}, y = {y}");

    // `..` skips the fields (or items) you do not name
    let color = Rgb(200, 100, 50);
    let Rgb(red, ..) = color;
    let Rgb(_, green, blue) = color;
    let (first, .., last) = (1, 2, 3, 4);
    println!("red = {red}, green = {green}, blue = {blue}");
    println!("first = {first}, last = {last}");

    // patterns nest as deep as the data does
    let shapes = [
        Shape::Circle {
            center: Point { x: 0, y: 0 },
            radius: 2,
        },
        Shape::Circle {
            center: Point { x: 5, y: 1 },
            radius: 3,
        },
        Shape::Rect(Point { x: 1, y: 1 }, Point { x: 4, y: 3 }),
    ];
    for shape in &shapes {
        println!("{}", describe(shape));
    }

    // an Option of a pair, and a pair of Options
    let found = Some(("ana", 30));
    if let Some((name, age)) = found {
        println!("{name} is {age}");
    }
    match (Some(1), None::<i32>) {
        (Some(a), Some(b)) => println!("both: {a} {b}"),
        (Some(a), None) | (None, Some(a)) => println!("exactly one: {a}"),
        (None, None) => println!("neither"),
    }
}

